export const hasIcon = (name) => !!MAP[name];

export default function Icon({ name, size = 18, className = '', strokeWidth = 2, ...rest }) {
  const C = MAP[name] || MAP.circle;
  return <C size={size} strokeWidth={strokeWidth} className={'ic ' + className} aria-hidden="true" {...rest} />;
}
